def read_file(disk, table, name):
    if name not in table:
        return None
    blocks, size = table[name]
    return "".join(disk[b] for b in blocks)[:size]

def free_blocks(disk, table):
    used = set()
    for blocks, size in table.values():
        used.update(blocks)
    return [b for b in range(len(disk)) if b not in used]

unitTests:
DISK = ["Hell", "xxxx", "o, w", "orld", "Bye!", "....", "abcd"]
TABLE = {"hello.txt": ([0, 2, 3], 12), "bye.txt": ([4], 3), "back.txt": ([6, 5], 6)}

@test("reading files")
def _():
    check_eq(read_file(DISK, TABLE, "hello.txt"), "Hello, world")
    check_eq(read_file(DISK, TABLE, "bye.txt"), "Bye")
    check_eq(read_file(DISK, TABLE, "back.txt"), "abcd..")

@test("a missing file")
def _():
    check_eq(read_file(DISK, TABLE, "nope.txt"), None)

@test("free blocks")
def _():
    check_eq(free_blocks(DISK, TABLE), [1])
    check_eq(free_blocks(["aaaa", "bbbb"], {}), [0, 1])

